"""Thirty-second two-actor Native capture proposal; CPU preflight is offline."""
from pathlib import Path
import argparse
import json
import math
import xml.etree.ElementTree as ET

ASSIGNMENT = 'training__C111294__LVMC-11-12-070-B__motor_vehicle_driver'
FRAMES = 600
RATE_HZ = 20
CAMERAS = (('overview', 1920, 1080), ('approach', 1280, 720),
           ('reference_corner', 1280, 720), ('driver_reference', 1280, 720))
HERE = Path(__file__).resolve().parent


def request(index, case):
    if type(index) is not int or not 0 <= index < FRAMES:
        raise ValueError('Frame outside exact 30-second request')
    if case not in (ASSIGNMENT + '__probe_1', ASSIGNMENT + '__probe_2'):
        raise ValueError('Unknown proposed case')
    # Engineering timing requests only. The actual actor histories must be read
    # back from CARLA, never inferred from this request schedule.
    ego_speed = (8.0 if index < 142 or index >= 335 else 0.0) if case.endswith('probe_1') else 8.0
    entrant_speed = 0.0 if index < 110 else (2.0 if index < 320 else 5.0)
    return {'through_target_speed_mps': ego_speed,
            'entrant_target_speed_mps': entrant_speed,
            'requested_yield_hold': case.endswith('probe_1') and 142 <= index < 335}


def capture_row(index, frame, elapsed_s, through, entrant):
    """Extract observed post-tick CARLA body/pose/velocity for later capture code."""
    if type(index) is not int or not 0 <= index < FRAMES or type(frame) is not int:
        raise ValueError('Native frame identity absent')
    if not isinstance(elapsed_s, (int, float)) or not math.isfinite(elapsed_s):
        raise ValueError('Native elapsed time absent')
    actors = {}
    for name, actor in (('through', through), ('entrant', entrant)):
        transform = actor.get_transform()
        velocity = actor.get_velocity()
        vertices = actor.bounding_box.get_world_vertices(transform)
        if len(vertices) != 8:
            raise ValueError('Full Native vehicle body absent')
        actors[name] = {'actor_id': actor.id, 'blueprint_id': actor.type_id,
                        'x_m': transform.location.x, 'y_m': transform.location.y,
                        'speed_mps': math.sqrt(velocity.x**2 + velocity.y**2 + velocity.z**2),
                        'body_vertices_m': [[v.x, v.y, v.z] for v in vertices]}
    return {'video_frame': index, 'native_frame': frame, 'time_s': elapsed_s,
            'through': actors['through'], 'entrant': actors['entrant'],
            'source_kind': 'native_observation'}


def check(config):
    if (config.get('law_id'), config.get('cell_id'), config.get('actor')) != (
            'LVMC-11-12-070-B', 'C111294', 'motor_vehicle_driver'):
        raise ValueError('Exact frozen case identity differs')
    if config['case_id'] not in (ASSIGNMENT + '__probe_1', ASSIGNMENT + '__probe_2'):
        raise ValueError('Exact frozen case identity differs')
    if config.get('rate_hz') != RATE_HZ or config.get('duration_s') != 30:
        raise ValueError('Full 600-frame duration differs')
    declared = [(camera['name'], camera['width'], camera['height'])
                for camera in config.get('cameras', [])]
    if declared != list(CAMERAS):
        raise ValueError('Current four-camera profile differs')
    tree = ET.parse(HERE / 'authored-road.xodr')
    roads = {int(item.attrib['id']) for item in tree.findall('road')}
    links = {(item.attrib['incomingRoad'], item.attrib['connectingRoad'])
             for item in tree.findall('junction/connection')}
    if roads != {1, 2, 3, 4, 13, 14} or not {('1', '13'), ('3', '14')} <= links:
        raise ValueError('Authored through/entrant geometry differs')
    if request(0, config['case_id'])['through_target_speed_mps'] <= 0:
        raise ValueError('Through approach request absent')
    expected_speed = 0 if config['case_id'].endswith('probe_1') else 8
    if request(200, config['case_id'])['through_target_speed_mps'] != expected_speed:
        raise ValueError('Through response request differs')
    return {'passed': True, 'case_id': config['case_id'], 'frames': FRAMES,
            'rate_hz': RATE_HZ, 'cameras': [item[0] for item in CAMERAS],
            'road_ids': sorted(roads), 'native_imported': False,
            'native_capture_implemented': False, 'physical_observation_claimed': False}


if __name__ == '__main__':
    parser = argparse.ArgumentParser()
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    if not args.check:
        raise SystemExit('Native capture loop and synchronized camera recorder remain unfinished')
    print(json.dumps(check(json.loads((HERE / 'config.json').read_text())), sort_keys=True))

"""Source-only 600-frame diagnostic for the entering-vehicle sequence.

Engineering speed tolerances classify the diagnostic motion; they are not legal cutoffs.
"""
from pathlib import Path
import hashlib
import json
import math
import xml.etree.ElementTree as ET

FRAMES = 600
RATE_HZ = 20
ASSIGNMENT = 'training__C111294__LVMC-11-12-070-B__motor_vehicle_driver'


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def measure(root, expected_case):
    root = Path(root)
    for name in ('road.xodr', 'native_samples.jsonl', 'source-manifest.json'):
        if not (root / name).is_file():
            raise ValueError('Missing required source: ' + name)
    manifest = json.loads((root / 'source-manifest.json').read_text())
    if manifest.get('case_id') != expected_case or manifest.get('source_kind') != 'synthetic_native_sample':
        raise ValueError('Diagnostic source identity differs')
    for name in ('road.xodr', 'native_samples.jsonl'):
        if manifest.get('sha256', {}).get(name) != sha(root / name):
            raise ValueError('Saved source hash differs: ' + name)
    tree = ET.parse(root / 'road.xodr')
    road_ids = {int(road.attrib['id']) for road in tree.findall('road')}
    links = {(item.attrib['incomingRoad'], item.attrib['connectingRoad'])
             for item in tree.findall('junction/connection')}
    if road_ids != {1, 2, 3, 4, 13, 14} or not {('1', '13'), ('3', '14')} <= links:
        raise ValueError('Through/entering intersection geometry differs')
    rows = [json.loads(line) for line in (root / 'native_samples.jsonl').read_text().splitlines()]
    if len(rows) != FRAMES:
        raise ValueError('Full 600-frame source window absent')
    stopped = []
    about = []
    entrant_in = []
    through_approach = []
    through_hold = []
    early_through_entry = []
    for index, row in enumerate(rows):
        if row.get('video_frame') != index or row.get('native_frame') != 100 + index:
            raise ValueError('Original frame join differs')
        if not math.isclose(row.get('time_s', -1), index / RATE_HZ, abs_tol=1e-6):
            raise ValueError('Original time join differs')
        ego, entrant = row.get('through'), row.get('entrant')
        if not isinstance(ego, dict) or not isinstance(entrant, dict):
            raise ValueError('Two participant histories required')
        if (ego.get('road_id') not in (1, 13, 4) or entrant.get('road_id') not in (3, 14, 2)
                or ego.get('lane_id') != -1 or entrant.get('lane_id') != -1):
            raise ValueError('Native road/lane roles differ')
        if any(not isinstance(actor.get(key), (int, float)) or not math.isfinite(actor[key])
               for actor in (ego, entrant) for key in ('x_m', 'y_m', 'speed_mps')):
            raise ValueError('Finite participant pose/speed absent')
        if ego['speed_mps'] < 0 or entrant['speed_mps'] < 0:
            raise ValueError('Negative speed source')
        if entrant['x_m'] < -7 and entrant['speed_mps'] <= .2:
            stopped.append(index)
        if -12 <= entrant['x_m'] <= -7 and entrant['speed_mps'] >= .5:
            about.append(index)
        if -7 <= entrant['x_m'] <= 7:
            entrant_in.append(index)
            if ego['y_m'] >= 7 and ego['speed_mps'] <= .3:
                through_hold.append(index)
        if 7 <= ego['y_m'] <= 30 and ego['speed_mps'] >= .5:
            through_approach.append(index)
        if about and entrant['x_m'] < 7 and ego['y_m'] < 7:
            early_through_entry.append(index)
    if len(stopped) < 40 or not about or min(about) <= max(stopped[:40]):
        raise ValueError('Entrant prior yield and about-to-enter sequence absent')
    if not entrant_in or not through_approach:
        raise ValueError('Crossing entrant or through approach absent')
    return {'format': 'c111294-yield-sequence-diagnostic-v1', 'case_id': expected_case,
            'frames': FRAMES, 'rate_hz': RATE_HZ, 'source_kind': 'synthetic_native_sample',
            'road_sha256': sha(root / 'road.xodr'),
            'native_samples_sha256': sha(root / 'native_samples.jsonl'),
            'entrant_prior_stopped_frames': len(stopped), 'about_to_enter_first_frame': min(about),
            'through_approach_frames': len(through_approach),
            'through_hold_during_entrant_frames': len(through_hold),
            'through_entered_before_entrant_clear': bool(early_through_entry),
            'through_yield_response_observed': bool(through_hold) and not early_through_entry,
            'through_highway_designation_physically_verified': False,
            'entrant_lawful_prior_yield_verified': False,
            'legal_verdict': None, 'physical_observation_claimed': False}

